files.content:
/* Palette: #1e293b (dark), #f8fafc (light), #3b82f6 (accent), #10b981 (success), #ef4444 (error) */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background: #1e293b;
  color: #f8fafc;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.card {
  background: #f8fafc;
  color: #1e293b;
  border-radius: 16px;
  padding: 2rem;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.3);
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 0.25rem;
  color: #1e293b;
}

.subtitle {
  font-size: 1rem;
  color: #475569;
  margin-bottom: 1.5rem;
}

.field {
  margin-bottom: 1.25rem;
}

label {
  display: block;
  font-weight: 600;
  font-size: 0.95rem;
  margin-bottom: 0.35rem;
  color: #1e293b;
}

input[type="number"] {
  width: 100%;
  padding: 0.75rem 1rem;
  font-size: 1rem;
  border: 2px solid #cbd5e1;
  border-radius: 8px;
  background: #ffffff;
  color: #1e293b;
  transition: border-color 0.15s, box-shadow 0.15s;
}

input[type="number"]:hover {
  border-color: #94a3b8;
}

input[type="number"]:focus {
  outline: none;
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.25);
}

input[type="number"]:active {
  border-color: #3b82f6;
}

.error {
  color: #ef4444;
  font-size: 0.9rem;
  font-weight: 500;
  margin-bottom: 1rem;
}

.actions {
  display: flex;
  gap: 0.75rem;
  margin-top: 0.5rem;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 0.75rem 1.5rem;
  border-radius: 8px;
  border: 2px solid transparent;
  cursor: pointer;
  transition: background-color 0.15s, border-color 0.15s, transform 0.05s;
}

.btn.secondary {
  background: #e2e8f0;
  color: #1e293b;
  border-color: #cbd5e1;
}

.btn.secondary:hover {
  background: #cbd5e1;
  border-color: #94a3b8;
}

.btn.secondary:focus {
  outline: none;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.35);
}

.btn.secondary:active {
  background: #94a3b8;
  transform: scale(0.98);
}

.results {
  margin-top: 1.5rem;
  padding-top: 1.5rem;
  border-top: 2px solid #e2e8f0;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.result-item {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 1.1rem;
}

.result-label {
  font-weight: 500;
  color: #475569;
}

.result-value {
  font-weight: 700;
  font-size: 1.35rem;
  color: #1e293b;
  font-variant-numeric: tabular-nums;
}

@media (max-width: 400px) {
  .card {
    padding: 1.25rem;
  }
  h1 {
    font-size: 1.4rem;
  }
  .result-item {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.15rem;
  }
}

(function () {
  'use strict';

  const distanceInput = document.getElementById('distance');
  const consumptionInput = document.getElementById('consumption');
  const priceInput = document.getElementById('price');
  const errorMessage = document.getElementById('error-message');
  const resultsSection = document.getElementById('results');
  const litresOutput = document.getElementById('litres');
  const totalCostOutput = document.getElementById('total-cost');
  const resetBtn = document.getElementById('reset-btn');

  const inputs = [distanceInput, consumptionInput, priceInput];

  function parseInput(value) {
    if (value.trim() === '') return null;
    const num = Number(value);
    if (!isFinite(num) || num < 0) return NaN;
    return num;
  }

  function calculate() {
    const distance = parseInput(distanceInput.value);
    const consumption = parseInput(consumptionInput.value);
    const price = parseInput(priceInput.value);

    if (distance === null || consumption === null || price === null) {
      resultsSection.hidden = true;
      errorMessage.hidden = true;
      return;
    }

    if (isNaN(distance) || isNaN(consumption) || isNaN(price)) {
      resultsSection.hidden = true;
      errorMessage.textContent = 'Please enter valid non-negative numbers.';
      errorMessage.hidden = false;
      return;
    }

    errorMessage.hidden = true;

    const litres = (distance * consumption) / 100;
    const totalCost = litres * price;

    litresOutput.textContent = litres.toFixed(2);
    totalCostOutput.textContent = totalCost.toFixed(2);
    resultsSection.hidden = false;
  }

  function reset() {
    inputs.forEach(function (input) {
      input.value = '';
    });
    resultsSection.hidden = true;
    errorMessage.hidden = true;
    errorMessage.textContent = '';
    distanceInput.focus();
  }

  inputs.forEach(function (input) {
    input.addEventListener('input', calculate);
    input.addEventListener('change', calculate);
  });

  resetBtn.addEventListener('click', reset);

  // Initial state
  resultsSection.hidden = true;
  errorMessage.hidden = true;
})();
